package datatypes;

public class Assign1Q10 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		double d = 120.20;
		double a = 135.60;

		System.out.println("sum of number: " + (d + a));
		System.out.println("diff of number: " + (d - a));
		System.out.println("multi of number: " + (d * a));
		System.out.println("divi of number: " + (d / a));
	}

}
